// Fixtures in test/fixtures are SYNTHETIC (generated by tools/make_fixtures.py). Never add real exports.
import 'dart:io';
import 'dart:typed_data';

import 'package:test/test.dart';
import 'package:wallet_importer/src/importer.dart' show fixMojibake, excelDate;
import 'package:wallet_importer/src/xls_reader.dart';
import 'package:wallet_importer/wallet_importer.dart';

Uint8List fixture(String name) => File('test/fixtures/$name').readAsBytesSync();

void main() {
  group('ids', () {
    test('match the v1 web app algorithm', () {
      expect(transactionId('2026-01-03', -1450, 'Wolt', 0), '2601031kc6rso');
      expect(transactionId('2026-01-07', -1450, 'Wolt', 1), '2601071tmyses_1');
      expect(transactionId('2026-01-15', 150000, 'Neto plaća za 12/2025', 0), '2601151qhfet5');
    });
    test('formatCents mirrors toFixed(2)', () {
      expect(formatCents(-33), '-0.33');
      expect(formatCents(0), '0.00');
      expect(formatCents(150000), '1500.00');
    });
  });

  group('helpers', () {
    test('excelDate', () => expect(excelDate(46037.0833), '2026-01-15'));
    test('fixMojibake', () {
      expect(fixMojibake('GraÅ¡o'), 'Grašo');
      expect(fixMojibake('Plain'), 'Plain');
      expect(fixMojibake('Već ispravno'), 'Već ispravno');
    });
  });

  group('PBZ .xls', () {
    test('reads the BIFF8 sheet including SST continuation records', () {
      final rows = XlsReader.firstSheet(fixture('pbz_synthetic.xls'));
      expect(rows.length, 419);
      expect(rows[3][1], 'TRANSAKCIJSKI RAČUN:');
      expect(rows[9], ['DATUM', 'VRSTA TRANSAKCIJE', 'OPIS PLAĆANJA', 'IZNOS', 'VALUTA']);
      expect(rows.last[2], startsWith('Plaćanje po računu br. 00399-ŠĐČĆŽ-'));
    });

    test('normalizes transactions and skips card holds', () {
      final b = importBankFile(fixture('pbz_synthetic.xls'));
      expect(b.source, 'pbz');
      expect(b.transactions.length, 408);
      expect(b.skipped, 1);
      final salary = b.transactions.first;
      expect(salary.date, '2026-01-15');
      expect(salary.amountMinor, 150000);
      expect(salary.currency, 'EUR');
      expect(salary.bankType, 'Plaća/Mirovina');
      expect(b.transactions.where((t) => t.description.contains('Revolut')).length, 2);
      final ids = b.transactions.map((t) => t.id).toSet();
      expect(ids.length, b.transactions.length);
      expect(b.transactions.firstWhere((t) => t.description.startsWith('Naknada')).amountMinor, -33);
    });

    test('re-import gives identical ids', () {
      final a = importBankFile(fixture('pbz_synthetic.xls')).transactions.map((t) => t.id).toList();
      final b = importBankFile(fixture('pbz_synthetic.xls')).transactions.map((t) => t.id).toList();
      expect(a, b);
    });
  });

  group('Revolut', () {
    test('.xlsx: completed rows only, fee deducted, text repaired', () {
      final b = importBankFile(fixture('revolut_synthetic.xlsx'));
      expect(b.source, 'revolut');
      expect(b.transactions.length, 6);
      expect(b.skipped, 1);
      expect(b.transactions.first.date, '2026-01-03');
      expect(b.transactions.first.bankType, 'Topup');
      final graso = b.transactions.firstWhere((t) => t.description == 'Grašo');
      expect(graso.amountMinor, -2050);
      final wolts = b.transactions.where((t) => t.date == '2026-01-07').map((t) => t.id).toList();
      expect(wolts, ['2601071tmyses', '2601071tmyses_1']);
    });

    test('.csv with quoted commas', () {
      final b = importBankFile(fixture('revolut_synthetic.csv'));
      expect(b.transactions.length, 2);
      expect(b.skipped, 1);
      expect(b.transactions.first.description, 'Shop, with comma');
      expect(b.transactions.first.amountMinor, -1230);
    });
  });

  test('unknown files are rejected', () {
    expect(() => importBankFile(Uint8List.fromList('hello,world\n1,2\n'.codeUnits)), throwsA(isA<ImportException>()));
  });
}
